function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 100) return 's must have 2 to 100 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (new Set(s).size === s.length) return 's must repeat at least one letter.';
  return null;
}

