function repeatedCharacter(s) {
  // For each letter of the alphabet, find where it occurs for the second time; keep the earliest.
  let best = '';
  let bestIndex = Infinity;
  for (let code = 97; code <= 122; code++) {
    const letter = String.fromCharCode(code);
    const first = s.indexOf(letter);
    if (first === -1) continue;
    const second = s.indexOf(letter, first + 1);
    if (second !== -1 && second < bestIndex) {
      bestIndex = second;
      best = letter;
    }
  }
  return best;
}

