function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const randomLetter = width => letters[Math.floor(rand() * width)];
  if (size === 'large') {
    // A run of distinct letters first pushes the first repeat late; 100 letters always repeat one.
    const pool = letters.split('');
    for (let i = pool.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    const head = pool.slice(0, Math.floor(rand() * 27)).join('');
    let s = head;
    while (s.length < 100) s += randomLetter(26);
    return [s];
  }
  for (;;) {
    const width = 1 + Math.floor(rand() * 5);
    const length = 2 + Math.floor(rand() * 7);
    let s = '';
    for (let i = 0; i < length; i++) s += randomLetter(width);
    if (new Set(s).size < s.length) return [s];
  }
}
